#!/usr/bin/env python3
"""Write sections/repro_d1.tex (d = 1 rows of the reproduction longtable) from data/quoted_numbers_d1.json."""
import json, re, sys
from pathlib import Path
H = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(H / 'tools')); from gen_numbers_d1 import tex
REC = {'winMinusRawRange': 'D, R', 'nrgDiffMin': 'D, NRG', 'nrgDiffMaxAbs': 'D, NRG', 'nrgAllAbove': 'D, NRG', 'gapExceedsSpread': 'D, NRG', 'tailShiftMax': 'D', 'nrgBracket': 'D, NRG', 'rawBelowWinAbove': 'D, R, NRG', 'winMinusRaw': 'D, R', 'winMinusRawMax': 'D, R', 'rawViol': 'ID', 'violN': 'ID', 'identN': 'ID', 'identRows': 'ID', 'winReduce': 'ID', 'resSig': 'ID', 'resE': 'ID', 'basisErrN32': 'D, R', 'nzSeries': 'R', 'nrgMax': 'D, NRG',
       'nrgDiffs': 'D, NRG', 'nrgPulls': 'D, NRG', 'nrgDiffN40': 'D, NRG', 'densTrain': 'B', 'densTeacher': 'B', 'densKeep': 'B', 'Asign': 'D'}
CMP = {'exact': 'exact', 'round': 'as quoted', 'paren': 'as quoted', 'range': 'as quoted', 'sig': 'sig.\\ figures', 'le': 'bound',
       'about': 'factor 2', 'true': 'true', 'status': 'status', 'list_sig1': '1 sig.\\ fig.', 'list_sig': 'sig.\\ figures', 'range_sigs': 'sig.\\ figures', 'list_round': 'as quoted', 'info': 'judgement'}
# Plain-text descriptions of quoted_numbers.json -> TeX: symbols and relations in math mode, other specials escaped.
TOK = [(r'note Table tab:d1-ident', r'Table~\ref{tab:d1-ident}'), (r'paper Table tab:win', r'copied in Ref.~\cite{paper}'),
       (r'\b[A-Z]\d+-[A-Z]\d+\b', lambda t: t.replace('-', '--')), (r'<=', r'$\le$'), (r'>=', r'$\ge$'), (r'->', r'$\to$'), (r'\bomega_eff\b', r'$\omega_{\rm eff}$'),
       (r'\bD_inf\b', r'$\Delta_\infty$'), (r'\bN_min\b', r'$N_{\min}$'), (r'\bDelta_eps\b', r'$\Delta_\varepsilon$'),
       (r'\bDelta\b', r'$\Delta_\varepsilon$'), (r'\bDs\b', r'$\Delta_\sigma$'), (r'\beps\^\d', lambda t: r'$\epsilon^%s$' % t[-1]),
       (r'\beps\b', r'$\epsilon$'), (r'\bomega\b', r'$\omega$'), (r'\bsigma\b', r'$\sigma$'), (r'\bphi\^3', r'$\phi^3$'), (r'\bepsilon\b', r'$\varepsilon$'),
       (r'\bnz\b', r'$n_z$'), (r'\bv1\b', r'$v_1$'), (r'(?<=\d) x (?=\d|\()', r' $\times$ '), (r'\^2', r'$^2$'),
       (r'[\w-]+(?:/[\w.-]+)+\.(?:json|md|py)\b', lambda t: r'\code{%s}' % esc(t)), (r'\|', r'$|$'), (r'~', r'$\sim$'), (r'<', r'$<$'), (r'>', r'$>$')]
PAT = re.compile('|'.join('(?P<t%d>%s)' % (i, p) for i, (p, _) in enumerate(TOK)))
def esc(s): return s.replace('\\', '\\textbackslash{}').replace('_', '\\_').replace('&', '\\&').replace('%', '\\%').replace('#', '\\#').replace('^', '\\^{}')
def tx(s):
    out, i = [], 0
    for m in PAT.finditer(s):
        k = next(j for j in range(len(TOK)) if m.group('t%d' % j) is not None); r = TOK[k][1]
        out += [esc(s[i:m.start()]), r(m.group(0)) if callable(r) else r]; i = m.end()
    return ''.join(out) + esc(s[i:])
Q = json.loads((H / 'data/quoted_numbers_d1.json').read_text())['numbers']
out = ['% Generated by tools/gen_repro_d1.py from data/quoted_numbers_d1.json. Package A = lri_dressed_phi4_hpc_analysis',
       '% (replay row = the id), records D = data/HT_1d/dens_v1, R = data/HT_1d/prod_window, B = dens_v1 bases, ID = identity records.',
       '\\multicolumn{6}{@{}p{\\linewidth}@{}}{\\emph{$d=1$, finite coupling} (A = \\texttt{lri\\_dressed\\_phi4\\_hpc\\_analysis}, '
       'I = \\texttt{lri\\_dressed\\_phi4\\_independent\\_check}; records D = \\texttt{data/HT\\_1d/dens\\_v1}, R = \\texttt{data/HT\\_1d/prod\\_window}, '
       'B = the stored bases in D, ID = \\texttt{identities/} in A, S = the solver \\texttt{lri\\_dressed\\_phi4\\_hpc}, NRG = \\texttt{results/HT\\_1d/nrg\\_reference.json}; expected values \\texttt{results/HT\\_1d/quoted\\_numbers.json}; tolerance ``status'': the stability flag behind the status word)}\\\\*']
for q in Q:
    v = q['quoted']
    numeric = lambda x: isinstance(x, (int, float)) or bool(re.fullmatch(r'[-+0-9.e()]+', str(x)))
    if 'display' in q: val = tx(q['display'])
    elif isinstance(v, bool): val = 'yes'
    elif isinstance(v, list) and all(numeric(x) for x in v): val = (', ' if q['compare'].startswith('list') else '--').join('$%s$' % tex(x) for x in v)
    elif numeric(v): val = '$' + tex(v) + '$'
    else: val = tx(str(v))
    what = tx(q['what'])
    out.append('%s & %s & A & %s & replay \\texttt{%s} & %s\\\\' % (what, val, REC.get(q.get('rule'), 'D' if q['compare'] != 'info' else '---'), q['id'], CMP[q['compare']]))
out += ['blind solver vs production, 38 points & $5\\times10^{-9}$ & I & I \\texttt{results/}, D, R & replay \\texttt{B6} (B4, B5) & 1 sig.\\ fig.\\\\',
        'blind solver vs dens16, $N\\le20$ & $\\le10^{-6}$ ($5.6\\times10^{-7}$) & I & same & replay \\texttt{B7} & bound\\\\',
        'weak coupling $C_2(N)$, $N\\le16$ & $\\le3\\times10^{-7}$ & I & I \\texttt{results/} & replay \\texttt{B8} & bound\\\\',
        'window at $O(\\eps^4)$ in the blind solver & exponent $\\approx4$ & I & I \\texttt{results/} & replay \\texttt{B9} & 3.8--4.3\\\\',
        'records intact and bound to the code & 1106 records & A, S & D, R & replay \\texttt{R1}--\\texttt{R7}, S \\texttt{F1}, \\texttt{F2} & exact\\\\',
        'rows, refits, tables & as shipped & A & D & replay \\texttt{W1}, \\texttt{A0}--\\texttt{A4}, \\texttt{T1} & exact; refit $\\le\\frac14$ half-spread\\\\']
(H / 'sections/repro_d1.tex').write_text('\n'.join(out) + '\n'); print('wrote sections/repro_d1.tex', len(out))
